  // Get the counter value for the given user.
  const counter = counters.find(counter => counter.user_id === user_id);

  // If the counter doesn't exist, create it.
  if (!counter) {
    counter = { user_id, counter: 0, timestamp };
    counters.push(counter);
  }

  // Increment the counter.
  counter.counter++;

  // Record the timestamp of the counter increment.
  counter.timestamp = timestamp;

  // Save the updated counter to the database.
  counters.save();
}

